var TABLE = { en, ja, my };
function t(lang, key2, params = {}) {
  const text = TABLE[lang]?.[key2] ?? en[key2];
  return text.replace(/\{(\w+)\}/g, (_, name323) => String(params[name323] ?? `{${name323}}`));
}
