// server/sprites.ts
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join as join2 } from "node:path";
async function resolveSprites(names, deps) {
  const custom2 = {};
  const missing = [];
  const wanted2 = [...new Set(names.map(slug).filter(Boolean))].filter((n3) => !(n3 in SPRITES));
  await Promise.all(
    wanted2.map(async (name323) => {
      const file2 = join2(deps.dir, `${name323}.json`);
      for (const dir of [deps.dir, ...deps.readDirs ?? []]) {
        try {
          const saved = JSON.parse(await readFile(join2(dir, `${name323}.json`), "utf8"));
          if (saved.frames?.every((f) => validateGrid(f) === null)) {
            custom2[name323] = saved;
            deps.log(`  \u25AB sprite "${name323}": from saved folder`);
            return;
          }
        } catch {
        }
      }
      deps.onDraw?.(name323.replace(/_/g, " "));
      const rows = await deps.generate(name323.replace(/_/g, " "));
      if (rows && validateGrid(rows) === null) {
        const data = { frames: [rows] };
        custom2[name323] = data;
        try {
          await mkdir(deps.dir, { recursive: true });
          await writeFile(file2, JSON.stringify(data, null, 1));
          deps.log(`  \u25AB sprite "${name323}": drawn by the AI and saved`);
        } catch {
          deps.log(`  \u25AB sprite "${name323}": drawn by the AI (could not be saved on this server)`);
        }
        return;
      }
      missing.push(name323);
      deps.log(`  \u25AB sprite "${name323}": MISSING, showing a placeholder (add it to the library)`);
    })
  );
  return { custom: custom2, missing };
}

// src/engine/quiz.ts
var letters = (s) => [...normalizeDigits(s).toLowerCase().replace(/[\s\p{P}\p{S}]+/gu, "")];
function overlap(a, b) {
  const x = letters(a);
  const y = letters(b);
  if (x.length < 2 || y.length < 2) return 0;
  const pairs = (c) => new Set(c.slice(1).map((ch, i) => c[i] + ch));
  const px = pairs(x);
  const py = pairs(y);
  let hit = 0;
  for (const p of px) if (py.has(p)) hit++;
  return hit / px.size;
}
var MIN_LETTERS = 10;
var TOO_SIMILAR = 0.6;
function quizProblems(verify2, question) {
  if (verify2.kind !== "choice" || verify2.correct === null) return [];
  const right = verify2.options[verify2.correct];
  if (!right || letters(right).length < MIN_LETTERS) return [];
  if (overlap(right, question) < TOO_SIMILAR) return [];
  return [
    `the quiz gives away its own answer: the right option "${right}" mostly repeats the question "${question}". Ask the learner to APPLY the idea to a NEW situation, and make the right option say something the question does not already say. The wrong options must be believable mistakes, not unrelated things.`
  ];
}

